184	// ---- 系列 ----
185	
186	// CreateSeries 登记一个系列，记录创建账户与文字元数据。创建账户必须
187	// 已登记且可用；后续只有该账户能发行该系列的藏品或封存该系列。
188	func (r *Registry) CreateSeries(id, creatorID, metadata string) error {
189		r.mu.Lock()
190		defer r.mu.Unlock()
191		if err := r.checkOpen(); err != nil {
192			return err
193		}
194		if strings.TrimSpace(id) == "" {
195			return fmt.Errorf("%w: 系列编号不能为空", ErrInvalidArgument)
196		}
197		creator, ok := r.state.Accounts[creatorID]
198		if !ok {
199			return fmt.Errorf("%w: 创建账户 %s", ErrNotFound, creatorID)
200		}
201		if !creator.Active {
202			return fmt.Errorf("%w: 创建账户 %s", ErrAccountInactive, creatorID)
203		}
204		if _, ok := r.state.Series[id]; ok {
205			return fmt.Errorf("%w: 系列 %s", ErrAlreadyExists, id)
206		}
207		r.state.Series[id] = series{ID: id, CreatorID: creatorID, Metadata: metadata}
208		return r.commit()
209	}
210	
211	// SealSeries 封存系列。只有系列创建账户可以封存；封存后不能继续发行，
212	// 已发行藏品仍可转让，且封存不能撤销。
213	func (r *Registry) SealSeries(seriesID, operator string) error {
214		r.mu.Lock()
215		defer r.mu.Unlock()
216		if err := r.checkOpen(); err != nil {
217			return err
218		}
219		s, ok := r.state.Series[seriesID]
220		if !ok {
221			return fmt.Errorf("%w: 系列 %s", ErrNotFound, seriesID)
222		}
223		if s.CreatorID != operator {
224			return fmt.Errorf("%w: 只有创建账户 %s 可以封存系列 %s", ErrForbidden, s.CreatorID, seriesID)
225		}
226		if s.Sealed {
227			return nil // 封存不可撤销，重复封存视为已处于封存态
228		}
229		s.Sealed = true
230		r.state.Series[seriesID] = s
231		return r.commit()
232	}
233	
234	// GetSeries 查询系列；不存在时返回包裹 ErrNotFound 的错误。
235	func (r *Registry) GetSeries(id string) (Series, error) {
236		r.mu.Lock()
237		defer r.mu.Unlock()
238		if err := r.checkOpen(); err != nil {
239			return Series{}, err
240		}
241		s, ok := r.state.Series[id]
242		if !ok {
243			return Series{}, fmt.Errorf("%w: 系列 %s", ErrNotFound, id)
244		}
245		return Series{ID: s.ID, CreatorID: s.CreatorID, Metadata: s.Metadata, Sealed: s.Sealed}, nil
246	}
