372	
373	func (req TransferRequest) validatePresent() error {
374		missing := []string{}
375		if strings.TrimSpace(req.Operator) == "" {
376			missing = append(missing, "operator")
377		}
378		if strings.TrimSpace(req.Reason) == "" {
379			missing = append(missing, "reason")
380		}
381		if strings.TrimSpace(req.RequestID) == "" {
382			missing = append(missing, "request_id")
383		}
384		if strings.TrimSpace(req.ItemID) == "" {
385			missing = append(missing, "item_id")
386		}
387		if strings.TrimSpace(req.ExpectedOwner) == "" {
388			missing = append(missing, "expected_owner")
389		}
390		if strings.TrimSpace(req.ToID) == "" {
391			missing = append(missing, "to_id")
392		}
393		if req.ExpectedVer <= 0 {
394			missing = append(missing, "expected_version")
395		}
396		if len(missing) > 0 {
397			return fmt.Errorf("%w: 转让请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
398		}
399		if req.Price < 0 {
400			return fmt.Errorf("%w: 成交价款 %d 不能为负", ErrInvalidArgument, req.Price)
401		}
402		return nil
403	}
404	
405	func transferParamsSig(req TransferRequest) string {
406		// Price 用 omitempty：价款为 0 时签名与引入价款前的旧格式一致，
407		// 旧登记册中落盘的请求仍可按原参数回放；改价则签名不同、按请求号
408		// 冲突拒绝。
409		b, _ := json.Marshal(struct {
410			Kind          string `json:"kind"`
411			ItemID        string `json:"item_id"`
412			ExpectedOwner string `json:"expected_owner"`
413			ExpectedVer   int64  `json:"expected_version"`
414			ToID          string `json:"to_id"`
415			Price         int64  `json:"price,omitempty"`
416			Reason        string `json:"reason"`
417		}{"transfer", req.ItemID, req.ExpectedOwner, req.ExpectedVer, req.ToID, req.Price, req.Reason})
418		return string(b)
419	}
420	
421	// transferOutcome 是一笔成功转让落盘后的执行结果，供各转让入口组装
422	// 各自的返回结构与请求记录。
423	type transferOutcome struct {
424		seq     int64      // 转让历史序号
425		fromID  string     // 转让前持有人
426		fromVer int64      // 转让前持有版本
427		royalty royaltyRec // 版税应付记录（含价款、明细与余款）
428	}
429	
430	// toVer 是转让后的持有版本。
431	func (o transferOutcome) toVer() int64 { return o.fromVer + 1 }
432	
433	// applyTransfer 完成一笔成功转让的全部状态变化：持有版本加一并换主、
434	// 追加转让历史、按所属系列的版税规则快照计算应付明细与归转让前持有人
435	// 的余款。直接转让、授权代转与整批转让共用这一段逻辑，保证同一笔转让
436	// 的持有、历史与金额记录始终一致；authID 为空表示直接转让。调用方负责
437	// 前置校验、请求结果登记与落盘，调用时必须持有锁且校验已通过。
438	func (r *Registry) applyTransfer(itemID, toID, operator, reason, requestID, authID string, price int64) transferOutcome {
439		h := r.state.Holdings[itemID]
440		seq := r.state.NextSeq + 1
441		r.state.NextSeq = seq
442		from := h.OwnerID
443		fromVer := h.Version
444		h.OwnerID = toID
445		h.Version = fromVer + 1
446		r.state.Holdings[itemID] = h
447		r.state.History = append(r.state.History, historyEntry{
448			Seq: seq, Kind: "transfer", ItemID: itemID, Operator: operator,
449			Reason: reason, RequestID: requestID,
450			FromID: from, ToID: toID, FromVersion: fromVer, ToVersion: fromVer + 1,
451			AuthID: authID,
452		})
453		// 版税按所属系列的规则快照计算；余款归转让前持有人。
454		it := r.state.Items[itemID]
455		royalty := newRoyaltyRec(seq, itemID, it.SeriesID, price,
456			r.state.Series[it.SeriesID].Royalty, from)
457		r.state.Royalties[seq] = royalty
458		return transferOutcome{seq: seq, fromID: from, fromVer: fromVer, royalty: royalty}
459	}
460	
461	// Transfer 由当前持有人发起转让。接收人必须已登记、可用且不同于当前
462	// 持有人；请求必须给出期望持有人与期望版本，藏品不存在或持有人/版本
463	// 不符时返回业务拒绝且不改变任何状态。成交价款（分）由持有人填写，
464	// 非负、未填按 0；成功时按所属系列的版税规则一次落盘各收款账户的
465	// 应付明细与归转让前持有人的余款。同一 (操作者, 请求号) 的相同
466	// 请求重复提交（即使藏品后来已易手）返回首次结果。
467	//
468	// 状态类拒绝的落盘失败时，与整批转让一致：返回保存错误（保留实际写入
469	// 错误）而非该业务错误，结果为空（无藏品编号、无持有变化、无历史序号、
470	// 无金额、业务错误为空、不标回放），请求号不被这次未保存的拒绝占用；
471	// 保存条件恢复后用完全相同的请求重提，按当时的业务状态重新判断：拒绝
472	// 条件仍在则重新保存此次拒绝并返回对应业务错误，状态已变为满足请求则
473	// 正常转出。
474	func (r *Registry) Transfer(req TransferRequest) (TransferResult, error) {
475		if err := req.validatePresent(); err != nil {
476			return TransferResult{}, err
477		}
478		r.mu.Lock()
479		defer r.mu.Unlock()
480		if err := r.checkOpen(); err != nil {
481			return TransferResult{}, err
482		}
483	
484		key := requestKey(req.Operator, req.RequestID)
485		sig := transferParamsSig(req)
486		if prev, ok := r.state.Requests[key]; ok {
487			return r.replayTransfer(prev, sig)
488		}
489	
490		bizErr := r.checkTransfer(req)
491		if bizErr != nil {
492			if !isValidationErr(bizErr) {
493				// 状态类业务拒绝（持有人/版本不符、账户停用、收发同人等）
494				// 占用请求号并落盘，相同参数重提永远返回这一次拒绝。
495				r.state.Requests[key] = request{
496					Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
497					Params: sig, Rejected: true, Reason: errCode(bizErr),
498					ItemID: req.ItemID,
499				}
500				if err := r.commit(); err != nil {
501					// 拒绝结果落盘失败：这次拒绝没有被记住，与整批转让一致——
502					// 不能只用业务错误掩盖保存错误，调用者稍后用原请求重提时
503					// 必须按当时状态重新判断，而不是回放一个实际没有保存的
504					// 拒绝。commit 失败时已按磁盘内容重建状态，请求记录随之
505					// 撤销；此处再删一次以覆盖磁盘暂时不可读、状态未能重建
506					// 的情形。整体返回空结果：无藏品编号、无持有变化、无历史
507					// 序号、无金额、不标回放、结果中业务错误为空，error 保留
508					// 实际写入错误。
509					delete(r.state.Requests, key)
510					return TransferResult{}, err
511				}
512			}
513			// 藏品或账户不存在等校验错误不占用请求号，也不改变持有或历史。
514			return TransferResult{ItemID: req.ItemID, Err: bizErr}, bizErr
515		}
516	
517		// 持有变化、历史、版税应付与请求结果在同一临界区内一次落盘。
518		out := r.applyTransfer(req.ItemID, req.ToID, req.Operator, req.Reason, req.RequestID, "", req.Price)
519		r.state.Requests[key] = request{
520			Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
521			Params: sig, ItemID: req.ItemID, FromID: out.fromID, ToID: req.ToID,
522			Version: out.toVer(), TxSeq: out.seq,
523		}
524		if err := r.commit(); err != nil {
525			return TransferResult{}, err
526		}
527		return TransferResult{ItemID: req.ItemID, FromID: out.fromID, ToID: req.ToID,
528			Version: out.toVer(), TxSeq: out.seq,
529			Price: out.royalty.Price, Payables: publicPayables(out.royalty.Payees),
530			Remainder: out.royalty.Remainder}, nil
531	}
532	
533	// checkTransfer 按单件转让的优先级执行与整批共用的直接转让资格规则：
534	// 参数合法后，藏品及持有记录不存在优先于账户错误，操作者的登记和停用
535	// 问题优先于接收账户问题，接收账户问题优先于收发同人，收发同人又优先
536	// 于持有信息不符。
537	func (r *Registry) checkTransfer(req TransferRequest) error {
538		return r.checkSingleTransferEligibility(directTransferEligibility{
539			itemID:        req.ItemID,
540			operator:      req.Operator,
541			toID:          req.ToID,
542			expectedOwner: req.ExpectedOwner,
543			expectedVer:   req.ExpectedVer,
544		})
545	}
546	
547	func (r *Registry) replayTransfer(prev request, sig string) (TransferResult, error) {
548		if prev.Kind != "transfer" || prev.Params != sig {
549			return TransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
550				ErrRequestConflict, prev.Operator, prev.RequestID)
551		}
552		res := TransferResult{ItemID: prev.ItemID, FromID: prev.FromID, ToID: prev.ToID,
553			Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
554		if prev.Rejected {
555			res.Err = codeErr(prev.Reason)
556			return res, res.Err
557		}
558		// 回放首次成功的金额：即使藏品后来再次易手或进程重开，仍返回原
559		// 价款与应付明细，不重复计入。
560		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
561		return res, nil
562	}
563	
564	// ---- 限时一次性代转授权 ----
565	
566	// authzCurrentStatus 计算授权当前状态。撤销与使用是落盘的终态；到期不
567	// 落盘，按当前时间实时判断——从到期时间点起即视为已过期。
568	func authzCurrentStatus(a authzRec, now time.Time) string {
569		switch a.Status {
570		case "revoked":
571			return AuthRevoked
572		case "used":
573			return AuthUsed
574		}
575		if !a.ExpiresAt.IsZero() && !now.Before(a.ExpiresAt) {
576			return AuthExpired
577		}
578		return AuthActive
579	}
