581	func (req CreateAuthorizationRequest) validatePresent() error {
582		missing := []string{}
583		if strings.TrimSpace(req.Operator) == "" {
584			missing = append(missing, "operator")
585		}
586		if strings.TrimSpace(req.Reason) == "" {
587			missing = append(missing, "reason")
588		}
589		if strings.TrimSpace(req.RequestID) == "" {
590			missing = append(missing, "request_id")
591		}
592		if strings.TrimSpace(req.AuthID) == "" {
593			missing = append(missing, "auth_id")
594		}
595		if strings.TrimSpace(req.ItemID) == "" {
596			missing = append(missing, "item_id")
597		}
598		if strings.TrimSpace(req.TrusteeID) == "" {
599			missing = append(missing, "trustee_id")
600		}
601		if strings.TrimSpace(req.ToID) == "" {
602			missing = append(missing, "to_id")
603		}
604		if strings.TrimSpace(req.ExpectedOwner) == "" {
605			missing = append(missing, "expected_owner")
606		}
607		if req.ExpectedVer <= 0 {
608			missing = append(missing, "expected_version")
609		}
610		if req.ExpiresAt.IsZero() {
611			missing = append(missing, "expires_at")
612		}
613		if len(missing) > 0 {
614			return fmt.Errorf("%w: 创建授权请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
615		}
616		if req.Price < 0 {
617			return fmt.Errorf("%w: 成交价款 %d 不能为负", ErrInvalidArgument, req.Price)
618		}
619		return nil
620	}
