622	func createAuthzParamsSig(req CreateAuthorizationRequest) string {
623		// Price 用 omitempty：价款为 0 时签名与旧格式一致，旧授权创建请求
624		// 仍可回放；改价则按请求号冲突拒绝。
625		b, _ := json.Marshal(struct {
626			Kind          string `json:"kind"`
627			AuthID        string `json:"auth_id"`
628			ItemID        string `json:"item_id"`
629			TrusteeID     string `json:"trustee_id"`
630			ToID          string `json:"to_id"`
631			ExpectedOwner string `json:"expected_owner"`
632			ExpectedVer   int64  `json:"expected_version"`
633			ExpiresAt     string `json:"expires_at"`
634			Price         int64  `json:"price,omitempty"`
635			Reason        string `json:"reason"`
636		}{"auth_create", req.AuthID, req.ItemID, req.TrusteeID, req.ToID,
637			req.ExpectedOwner, req.ExpectedVer,
638			req.ExpiresAt.UTC().Format(time.RFC3339Nano), req.Price, req.Reason})
639		return string(b)
640	}
641	
642	// CreateAuthorization 由当前持有人为一件已发行藏品创建限时、一次性的
643	// 代转授权：指定唯一授权编号、受托账户、固定接收账户、绝对到期时间，
644	// 以及期望持有人与期望版本。授权绑定创建时的持有版本，不改变持有关系，
645	// 也不限制持有人继续直接转让。受托人不能是授权人；受托人可与接收人
646	// 相同，但接收人也不能是授权人。到期时间必须晚于当前时间。
647	//
648	// 请求号与发行、转让共用同一操作者的请求号范围：相同业务参数重提返回
649	// 首次结果（成功或状态类业务拒绝），参数变化返回 ErrRequestConflict；
650	// 参数错误与引用不存在不占用请求号。
651	func (r *Registry) CreateAuthorization(req CreateAuthorizationRequest) (CreateAuthorizationResult, error) {
652		if err := req.validatePresent(); err != nil {
653			return CreateAuthorizationResult{}, err
654		}
655		r.mu.Lock()
656		defer r.mu.Unlock()
657		if err := r.checkOpen(); err != nil {
658			return CreateAuthorizationResult{}, err
659		}
660	
661		now := r.now()
662		key := requestKey(req.Operator, req.RequestID)
663		sig := createAuthzParamsSig(req)
664		if prev, ok := r.state.Requests[key]; ok {
665			return r.replayCreateAuthz(prev, sig)
666		}
667	
668		if bizErr := r.checkCreateAuthorization(req, now); bizErr != nil {
669			if !isValidationErr(bizErr) {
670				// 状态类业务拒绝（编号占用、停用、同人、版本不符、到期时间
671				// 已过等）占用请求号并落盘；参数错误与引用不存在不占用。
672				r.state.Requests[key] = request{
673					Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
674					Params: sig, Rejected: true, Reason: errCode(bizErr),
675					AuthID: req.AuthID, ItemID: req.ItemID,
676				}
677				_ = r.commit()
678			}
679			return CreateAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
680		}
681	
682		h := r.state.Holdings[req.ItemID]
683		a := authzRec{
684			ID: req.AuthID, ItemID: req.ItemID, GranterID: req.Operator,
685			TrusteeID: req.TrusteeID, ToID: req.ToID, ExpiresAt: req.ExpiresAt,
686			GrantVer: h.Version, Price: req.Price, CreatedAt: now,
687		}
688		r.state.Authzs[req.AuthID] = a
689		authSeq := r.state.NextAuthSeq + 1
690		r.state.NextAuthSeq = authSeq
691		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
692			Seq: authSeq, AuthID: req.AuthID, ItemID: req.ItemID, Kind: "create",
693			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
694			FromStatus: "", ToStatus: AuthActive, OccurredAt: now,
695		})
696		r.state.Requests[key] = request{
697			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
698			Params: sig, AuthID: req.AuthID, ItemID: req.ItemID, Version: h.Version,
699		}
700		if err := r.commit(); err != nil {
701			return CreateAuthorizationResult{}, err
702		}
703		return CreateAuthorizationResult{AuthID: req.AuthID, Status: AuthActive, GrantVer: h.Version}, nil
704	}
705	
706	func (r *Registry) checkCreateAuthorization(req CreateAuthorizationRequest, now time.Time) error {
707		h, ok := r.state.Holdings[req.ItemID]
708		if !ok {
709			if _, itemExists := r.state.Items[req.ItemID]; !itemExists {
710				return fmt.Errorf("%w: 藏品 %s", ErrNotFound, req.ItemID)
711			}
712			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, req.ItemID)
713		}
714		op, ok := r.state.Accounts[req.Operator]
715		if !ok {
716			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, req.Operator)
717		}
718		trustee, ok := r.state.Accounts[req.TrusteeID]
719		if !ok {
720			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.TrusteeID)
721		}
722		to, ok := r.state.Accounts[req.ToID]
723		if !ok {
724			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, req.ToID)
725		}
726		if req.TrusteeID == req.Operator {
727			return fmt.Errorf("%w: 受托人不能是授权人 %s", ErrSameAccount, req.Operator)
728		}
729		if req.ToID == req.Operator {
730			return fmt.Errorf("%w: 接收人不能是授权人 %s", ErrSameAccount, req.Operator)
731		}
732		if !op.Active {
733			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, req.Operator)
734		}
735		if !trustee.Active {
736			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.TrusteeID)
737		}
738		if !to.Active {
739			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, req.ToID)
740		}
741		// 授权编号占用是对象级冲突，优先于当前时间与持有版本检查。
742		if _, exists := r.state.Authzs[req.AuthID]; exists {
743			return fmt.Errorf("%w: 授权编号 %s 已被占用", ErrAlreadyExists, req.AuthID)
744		}
745		// 到期时间不晚于当前时间即为参数错误；从到期时间点起不可使用。
746		if !req.ExpiresAt.After(now) {
747			return fmt.Errorf("%w: 到期时间 %s 必须晚于当前时间",
748				ErrInvalidArgument, req.ExpiresAt.Format(time.RFC3339Nano))
749		}
750		if h.OwnerID != req.ExpectedOwner || h.Version != req.ExpectedVer ||
751			req.Operator != h.OwnerID {
752			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d",
753				ErrConflict, req.ItemID, h.OwnerID, h.Version)
754		}
755		return nil
756	}
757	
758	func (r *Registry) replayCreateAuthz(prev request, sig string) (CreateAuthorizationResult, error) {
759		if prev.Kind != "auth_create" || prev.Params != sig {
760			return CreateAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
761				ErrRequestConflict, prev.Operator, prev.RequestID)
762		}
763		res := CreateAuthorizationResult{AuthID: prev.AuthID, GrantVer: prev.Version,
764			Status: AuthActive, Replayed: true}
765		if prev.Rejected {
766			res.Err = codeErr(prev.Reason)
767			return res, res.Err
768		}
769		return res, nil
770	}
771	
772	func revokeAuthzParamsSig(req RevokeAuthorizationRequest) string {
773		b, _ := json.Marshal(struct {
774			Kind   string `json:"kind"`
775			AuthID string `json:"auth_id"`
776			Reason string `json:"reason"`
777		}{"auth_revoke", req.AuthID, req.Reason})
778		return string(b)
779	}
780	
781	// RevokeAuthorization 撤销一份尚未使用的代转授权。仅授权人可以撤销；
782	// 已使用的授权不能撤销（返回 ErrAuthorizationUsed）。授权已撤销时再次
783	// 撤销不新增授权变更记录，按成功返回。请求号语义与其他操作一致。
784	func (r *Registry) RevokeAuthorization(req RevokeAuthorizationRequest) (RevokeAuthorizationResult, error) {
785		missing := []string{}
786		if strings.TrimSpace(req.Operator) == "" {
787			missing = append(missing, "operator")
788		}
789		if strings.TrimSpace(req.Reason) == "" {
790			missing = append(missing, "reason")
791		}
792		if strings.TrimSpace(req.RequestID) == "" {
793			missing = append(missing, "request_id")
794		}
795		if strings.TrimSpace(req.AuthID) == "" {
796			missing = append(missing, "auth_id")
797		}
798		if len(missing) > 0 {
799			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 撤销授权请求缺少必填字段 %s",
800				ErrInvalidArgument, strings.Join(missing, ", "))
801		}
802		r.mu.Lock()
803		defer r.mu.Unlock()
804		if err := r.checkOpen(); err != nil {
805			return RevokeAuthorizationResult{}, err
806		}
807	
808		now := r.now()
809		key := requestKey(req.Operator, req.RequestID)
810		sig := revokeAuthzParamsSig(req)
811		if prev, ok := r.state.Requests[key]; ok {
812			return r.replayRevokeAuthz(prev, sig)
813		}
814	
815		a, ok := r.state.Authzs[req.AuthID]
816		if !ok {
817			// 引用不存在不占用请求号。
818			err := fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
819			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: err}, err
820		}
821		if a.GranterID != req.Operator {
822			bizErr := fmt.Errorf("%w: 只有授权人 %s 可以撤销授权 %s",
823				ErrForbidden, a.GranterID, req.AuthID)
824			r.recordAuthzRequest(key, sig, req, "auth_revoke", bizErr)
825			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
826		}
827		switch authzCurrentStatus(a, now) {
828		case AuthUsed:
829			bizErr := fmt.Errorf("%w: 授权 %s 已使用，不能撤销", ErrAuthorizationUsed, req.AuthID)
830			r.recordAuthzRequest(key, sig, req, "auth_revoke", bizErr)
831			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
832		case AuthRevoked:
833			// 已撤销是幂等终态：不新增授权变更记录；该请求号仍登记为成功，
834			// 相同请求重放回放同一结果。
835			r.state.Requests[key] = request{
836				Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
837				Params: sig, AuthID: req.AuthID,
838			}
839			if err := r.commit(); err != nil {
840				return RevokeAuthorizationResult{}, err
841			}
842			return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
843		}
844	
845		from := AuthActive
846		if authzCurrentStatus(a, now) == AuthExpired {
847			from = AuthExpired
848		}
849		a.Status = "revoked"
850		a.RevokedAt = now
851		r.state.Authzs[req.AuthID] = a
852		authSeq := r.state.NextAuthSeq + 1
853		r.state.NextAuthSeq = authSeq
854		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
855			Seq: authSeq, AuthID: req.AuthID, ItemID: a.ItemID, Kind: "revoke",
856			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
857			FromStatus: from, ToStatus: AuthRevoked, OccurredAt: now,
858		})
859		r.state.Requests[key] = request{
860			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
861			Params: sig, AuthID: req.AuthID,
862		}
863		if err := r.commit(); err != nil {
864			return RevokeAuthorizationResult{}, err
865		}
866		return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
867	}
868	
869	// recordAuthzRequest 记录授权类操作的状态类业务拒绝并尽力落盘。
870	func (r *Registry) recordAuthzRequest(key, sig string, req RevokeAuthorizationRequest, kind string, bizErr error) {
871		r.state.Requests[key] = request{
872			Operator: req.Operator, RequestID: req.RequestID, Kind: kind,
873			Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
874		}
875		_ = r.commit()
876	}
