878	func (r *Registry) replayRevokeAuthz(prev request, sig string) (RevokeAuthorizationResult, error) {
879		if prev.Kind != "auth_revoke" || prev.Params != sig {
880			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
881				ErrRequestConflict, prev.Operator, prev.RequestID)
882		}
883		res := RevokeAuthorizationResult{AuthID: prev.AuthID, Status: AuthRevoked, Replayed: true}
884		if prev.Rejected {
885			res.Err = codeErr(prev.Reason)
886			res.Status = ""
887			return res, res.Err
888		}
889		return res, nil
890	}
