892	func proxyTransferParamsSig(req ProxyTransferRequest) string {
893		b, _ := json.Marshal(struct {
894			Kind   string `json:"kind"`
895			AuthID string `json:"auth_id"`
896			Reason string `json:"reason"`
897		}{"proxy_transfer", req.AuthID, req.Reason})
898		return string(b)
899	}
