901	// ProxyTransfer 由受托人凭授权发起一次性代转。藏品与接收人均以授权
902	// 记载为准，请求本身不能指定。成功后持有人变为授权中的接收人、持有
903	// 版本加一，授权记为已使用并关联该笔转让；代转同样出现在藏品历史中，
904	// 操作者记为实际受托账户并可通过授权编号追溯。
905	//
906	// 非受托人（ErrForbidden）、授权已撤销（ErrAuthorizationRevoked）、
907	// 已到期（ErrAuthorizationExpired）、已使用（ErrAuthorizationUsed）、
908	// 任一相关账户停用（ErrAccountInactive）以及持有版本已变化
909	// （ErrConflict，即使藏品回到授权人手中也不恢复）分别明确拒绝，拒绝
910	// 不改变持有或授权状态。成功代转用原请求号重放时，即使授权已到期、
911	// 账户已停用或藏品再次易手，仍返回首次的转让结果。
912	func (r *Registry) ProxyTransfer(req ProxyTransferRequest) (ProxyTransferResult, error) {
913		missing := []string{}
914		if strings.TrimSpace(req.Operator) == "" {
915			missing = append(missing, "operator")
916		}
917		if strings.TrimSpace(req.Reason) == "" {
918			missing = append(missing, "reason")
919		}
920		if strings.TrimSpace(req.RequestID) == "" {
921			missing = append(missing, "request_id")
922		}
923		if strings.TrimSpace(req.AuthID) == "" {
924			missing = append(missing, "auth_id")
925		}
926		if len(missing) > 0 {
927			return ProxyTransferResult{}, fmt.Errorf("%w: 代转请求缺少必填字段 %s",
928				ErrInvalidArgument, strings.Join(missing, ", "))
929		}
930		r.mu.Lock()
931		defer r.mu.Unlock()
932		if err := r.checkOpen(); err != nil {
933			return ProxyTransferResult{}, err
934		}
935	
936		now := r.now()
937		key := requestKey(req.Operator, req.RequestID)
938		sig := proxyTransferParamsSig(req)
939		if prev, ok := r.state.Requests[key]; ok {
940			return r.replayProxyTransfer(prev, sig)
941		}
942	
943		if bizErr := r.checkProxyTransfer(req, now); bizErr != nil {
944			if !isValidationErr(bizErr) {
945				r.state.Requests[key] = request{
946					Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
947					Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
948				}
949				_ = r.commit()
950			}
951			return ProxyTransferResult{AuthID: req.AuthID, Err: bizErr}, bizErr
952		}
953	
954		a := r.state.Authzs[req.AuthID]
955		// 代转价款以授权创建时记载为准，执行时不得改价；余款归转让前持有
956		// 人（授权人），不记给受托人。持有变化、历史、应付明细与授权使用
957		// 状态在同一临界区内一次落盘；历史记录实际受托账户并可按授权编号
958		// 追溯。
959		out := r.applyTransfer(a.ItemID, a.ToID, req.Operator, req.Reason, req.RequestID, a.ID, a.Price)
960		a.Status = "used"
961		a.UsedTxSeq = out.seq
962		a.UsedAt = now
963		r.state.Authzs[a.ID] = a
964		authSeq := r.state.NextAuthSeq + 1
965		r.state.NextAuthSeq = authSeq
966		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
967			Seq: authSeq, AuthID: a.ID, ItemID: a.ItemID, Kind: "use",
968			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
969			FromStatus: AuthActive, ToStatus: AuthUsed, TxSeq: out.seq, OccurredAt: now,
970		})
971		r.state.Requests[key] = request{
972			Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
973			Params: sig, AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID, ToID: a.ToID,
974			Version: out.toVer(), TxSeq: out.seq,
975		}
976		if err := r.commit(); err != nil {
977			return ProxyTransferResult{}, err
978		}
979		return ProxyTransferResult{AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID,
980			ToID: a.ToID, Version: out.toVer(), TxSeq: out.seq,
981			Price: out.royalty.Price, Payables: publicPayables(out.royalty.Payees),
982			Remainder: out.royalty.Remainder}, nil
983	}
984	
985	func (r *Registry) checkProxyTransfer(req ProxyTransferRequest, now time.Time) error {
986		a, ok := r.state.Authzs[req.AuthID]
987		if !ok {
988			return fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
989		}
990		op, ok := r.state.Accounts[req.Operator]
991		if !ok {
992			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.Operator)
993		}
994		granter, gOk := r.state.Accounts[a.GranterID]
995		to, tOk := r.state.Accounts[a.ToID]
996		if req.Operator != a.TrusteeID {
997			return fmt.Errorf("%w: 账户 %s 不是授权 %s 的受托人",
998				ErrForbidden, req.Operator, req.AuthID)
999		}
1000		if !gOk {
1001			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, a.GranterID)
1002		}
1003		if !tOk {
1004			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, a.ToID)
1005		}
1006		if !op.Active {
1007			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.Operator)
1008		}
1009		if !granter.Active {
1010			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, a.GranterID)
1011		}
1012		if !to.Active {
1013			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, a.ToID)
1014		}
1015		switch authzCurrentStatus(a, now) {
1016		case AuthRevoked:
1017			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationRevoked, req.AuthID)
1018		case AuthExpired:
1019			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationExpired, req.AuthID)
1020		case AuthUsed:
1021			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationUsed, req.AuthID)
1022		}
1023		// 授权只在创建时绑定的持有版本上有效；版本单调递增，藏品即使回到
1024		// 授权人手中也不会回到旧版本，旧授权据此永久失效。
1025		h, ok := r.state.Holdings[a.ItemID]
1026		if !ok {
1027			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, a.ItemID)
1028		}
1029		if h.OwnerID != a.GranterID || h.Version != a.GrantVer {
1030			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d，授权绑定 %s 版本 %d",
1031				ErrConflict, a.ItemID, h.OwnerID, h.Version, a.GranterID, a.GrantVer)
1032		}
1033		return nil
1034	}
1035	
1036	func (r *Registry) replayProxyTransfer(prev request, sig string) (ProxyTransferResult, error) {
1037		if prev.Kind != "proxy_transfer" || prev.Params != sig {
1038			return ProxyTransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
1039				ErrRequestConflict, prev.Operator, prev.RequestID)
1040		}
1041		res := ProxyTransferResult{AuthID: prev.AuthID, ItemID: prev.ItemID, FromID: prev.FromID,
1042			ToID: prev.ToID, Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
1043		if prev.Rejected {
1044			res.Err = codeErr(prev.Reason)
1045			return res, res.Err
1046		}
1047		// 回放首次成功的金额：授权到期、账户停用或藏品再次易手后仍返回
1048		// 原价款与应付明细，不重复计入。
1049		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
1050		return res, nil
1051	}
1052	
1053	// ---- 授权查询 ----
1054	
1055	// GetAuthorization 按编号查询授权内容与撤销、使用状态。授权不存在时
1056	// 返回包裹 ErrNotFound 的错误；返回的 Status 按当前时间实时计算，
1057	// 到期但尚未终结的授权返回 AuthExpired。
1058	func (r *Registry) GetAuthorization(authID string) (Authorization, error) {
1059		r.mu.Lock()
1060		defer r.mu.Unlock()
1061		if err := r.checkOpen(); err != nil {
1062			return Authorization{}, err
1063		}
1064		a, ok := r.state.Authzs[authID]
1065		if !ok {
1066			return Authorization{}, fmt.Errorf("%w: 授权 %s", ErrNotFound, authID)
1067		}
1068		return Authorization{
1069			ID: a.ID, ItemID: a.ItemID, GranterID: a.GranterID, TrusteeID: a.TrusteeID,
1070			ToID: a.ToID, ExpiresAt: a.ExpiresAt, GrantVer: a.GrantVer, Price: a.Price,
1071			Status:    authzCurrentStatus(a, r.now()),
1072			UsedTxSeq: a.UsedTxSeq, UsedAt: a.UsedAt, CreatedAt: a.CreatedAt,
1073			RevokedAt: a.RevokedAt,
1074		}, nil
1075	}
1076	
1077	// AuthorizationHistory 按藏品查看授权变更记录（创建、撤销、使用），
1078	// 按发生先后排列；每条记录包含操作者、原因、请求号与前后状态。藏品
1079	// 不存在时返回包裹 ErrNotFound 的错误。
1080	func (r *Registry) AuthorizationHistory(itemID string) ([]AuthorizationEvent, error) {
1081		r.mu.Lock()
1082		defer r.mu.Unlock()
1083		if err := r.checkOpen(); err != nil {
1084			return nil, err
1085		}
1086		if _, ok := r.state.Items[itemID]; !ok {
1087			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1088		}
1089		out := make([]AuthorizationEvent, 0)
1090		for _, e := range r.state.AuthEvents {
1091			if e.ItemID != itemID {
1092				continue
1093			}
1094			out = append(out, AuthorizationEvent{
1095				Seq: e.Seq, AuthID: e.AuthID, ItemID: e.ItemID, Kind: e.Kind,
1096				Operator: e.Operator, Reason: e.Reason, RequestID: e.RequestID,
1097				FromStatus: e.FromStatus, ToStatus: e.ToStatus, TxSeq: e.TxSeq,
1098				OccurredAt: e.OccurredAt,
1099			})
1100		}
1101		return out, nil
1102	}
1103	
1104	// ---- 查询 ----
1105	
1106	// GetItem 查询单件藏品的静态登记信息；不存在时返回包裹 ErrNotFound 的错误。
1107	func (r *Registry) GetItem(id string) (Item, error) {
1108		r.mu.Lock()
1109		defer r.mu.Unlock()
1110		if err := r.checkOpen(); err != nil {
1111			return Item{}, err
1112		}
1113		it, ok := r.state.Items[id]
1114		if !ok {
1115			return Item{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, id)
1116		}
1117		return Item{ID: it.ID, SeriesID: it.SeriesID, BatchNo: it.BatchNo,
1118			Metadata: it.Metadata, IssuedTxID: it.IssuedTxID}, nil
1119	}
1120	
1121	// GetHolding 查询藏品当前持有状态；藏品不存在时返回包裹 ErrNotFound 的错误。
1122	func (r *Registry) GetHolding(itemID string) (Holding, error) {
1123		r.mu.Lock()
1124		defer r.mu.Unlock()
1125		if err := r.checkOpen(); err != nil {
1126			return Holding{}, err
1127		}
1128		h, ok := r.state.Holdings[itemID]
1129		if !ok {
1130			return Holding{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1131		}
1132		return Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version}, nil
1133	}
1134	
1135	// HoldingsOf 查询某账户当前持有的全部藏品。账户不存在时返回包裹
1136	// ErrNotFound 的错误；停用账户仍可正常查询。
1137	func (r *Registry) HoldingsOf(accountID string) ([]Holding, error) {
1138		r.mu.Lock()
1139		defer r.mu.Unlock()
1140		if err := r.checkOpen(); err != nil {
1141			return nil, err
1142		}
1143		if _, ok := r.state.Accounts[accountID]; !ok {
1144			return nil, fmt.Errorf("%w: 账户 %s", ErrNotFound, accountID)
1145		}
1146		out := make([]Holding, 0)
1147		for _, h := range r.state.Holdings {
1148			if h.OwnerID == accountID {
1149				out = append(out, Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version})
1150			}
1151		}
1152		sort.Slice(out, func(i, j int) bool { return out[i].ItemID < out[j].ItemID })
1153		return out, nil
1154	}
1155	
1156	// History 查询藏品的发行与历次成功转让，按发生先后排列。发行记录的
1157	// 前持有人为空、前版本为 0。重复提交不会产生额外历史。藏品不存在时
1158	// 返回包裹 ErrNotFound 的错误。
1159	func (r *Registry) History(itemID string) ([]HistoryEntry, error) {
1160		r.mu.Lock()
1161		defer r.mu.Unlock()
1162		if err := r.checkOpen(); err != nil {
1163			return nil, err
1164		}
1165		if _, ok := r.state.Items[itemID]; !ok {
1166			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1167		}
1168		out := make([]HistoryEntry, 0)
1169		for _, e := range r.state.History {
1170			if e.ItemID != itemID {
1171				continue
1172			}
1173			out = append(out, HistoryEntry{
1174				Seq: e.Seq, Kind: e.Kind, ItemID: e.ItemID, Operator: e.Operator,
1175				Reason: e.Reason, RequestID: e.RequestID, FromID: e.FromID, ToID: e.ToID,
1176				FromVersion: e.FromVersion, ToVersion: e.ToVersion, AuthID: e.AuthID,
1177			})
1178		}
1179		return out, nil
1180	}
1181	
1182	// ---- 幂等辅助 ----
1183	
1184	// requestKey 由完整的操作者账户编号与完整的请求号共同确定一条请求记录。
1185	// 采用 JSON 数组编码而非直接拼接：账户编号或请求号本身允许包含零字符
1186	// （U+0000）等任意字符，直接拼接会让 ("a", "b\x00c") 与 ("a\x00b", "c")
1187	// 之类不同的组合得到相同的键，导致不同账户互相占用请求号、回放别人的
1188	// 结果。JSON 编码对任意字符都无歧义，两个组成部分各自完整参与键的构成。
1189	func requestKey(operator, requestID string) string {
1190		b, _ := json.Marshal([2]string{operator, requestID})
1191		return string(b)
1192	}
1193	
1194	// isValidationErr 判定是否为请求本身不成立的错误：必填缺失，或引用了
1195	// 不存在的账户、系列、藏品。这类请求不占用请求号、不落任何记录，引用
1196	// 对象后来补建后仍可用原请求号完整执行一次；其余拒绝（封存、停用、
1197	// 版本冲突、无权、编号已用、收发同人等状态类业务拒绝）按首次结果记忆
1198	// 并回放。
1199	func isValidationErr(err error) bool {
1200		return errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrNotFound)
1201	}
1202	
1203	var errCodes = map[error]string{
1204		ErrNotFound:             "not_found",
1205		ErrAlreadyExists:        "already_exists",
1206		ErrAccountInactive:      "account_inactive",
1207		ErrSeriesSealed:         "series_sealed",
1208		ErrConflict:             "conflict",
1209		ErrSameAccount:          "same_account",
1210		ErrForbidden:            "forbidden",
1211		ErrAuthorizationRevoked: "authorization_revoked",
1212		ErrAuthorizationExpired: "authorization_expired",
1213		ErrAuthorizationUsed:    "authorization_used",
1214		ErrRoyaltyFrozen:        "royalty_frozen",
1215		ErrSplitIntentRejected:  "split_intent_rejected",
1216		ErrSplitIntentWithdrawn: "split_intent_withdrawn",
1217		ErrSplitIntentInvalid:   "split_intent_invalid",
1218		ErrSplitIntentExpired:   "split_intent_expired",
1219		ErrSplitAnswered:        "split_answered",
1220	}
1221	
1222	var codeErrs = map[string]error{
1223		"not_found":              ErrNotFound,
1224		"already_exists":         ErrAlreadyExists,
1225		"account_inactive":       ErrAccountInactive,
1226		"series_sealed":          ErrSeriesSealed,
1227		"conflict":               ErrConflict,
1228		"same_account":           ErrSameAccount,
1229		"forbidden":              ErrForbidden,
1230		"authorization_revoked":  ErrAuthorizationRevoked,
1231		"authorization_expired":  ErrAuthorizationExpired,
1232		"authorization_used":     ErrAuthorizationUsed,
1233		"royalty_frozen":         ErrRoyaltyFrozen,
1234		"split_intent_rejected":  ErrSplitIntentRejected,
1235		"split_intent_withdrawn": ErrSplitIntentWithdrawn,
1236		"split_intent_invalid":   ErrSplitIntentInvalid,
1237		"split_intent_expired":   ErrSplitIntentExpired,
1238		"split_answered":         ErrSplitAnswered,
1239	}
1240	
1241	func errCode(err error) string {
1242		for sentinel, code := range errCodes {
1243			if errors.Is(err, sentinel) {
1244				return code
1245			}
1246		}
1247		return "rejected"
1248	}
1249	
1250	func codeErr(code string) error {
1251		if e, ok := codeErrs[code]; ok {
1252			return e
1253		}
1254		return errors.New("registry: 请求曾被拒绝")
1255	}
